color.script:
'use strict';
let previous = '';
export function update(value) {
 const p = input.cursorScreenPosition;
 if (input.cursorLeftDown) shared.cwbPolledDown = true;
 const key = [Math.round(p.x), Math.round(p.y), shared.cwbDown || 0, shared.cwbClicks || 0].join(',');
 if (key !== previous) { console.log('CWB_SCENE_POINTER', key, engine.screenResolution.x, engine.screenResolution.y); previous = key; }
 const r = Math.max(0, Math.min(1, p.x / engine.screenResolution.x));
 const g = Math.max(0, Math.min(1, p.y / engine.screenResolution.y));
 const b = 0.1 + (shared.cwbPolledDown ? 0.15 : 0) + 0.25 * ((shared.cwbDown || 0) % 2) + 0.45 * ((shared.cwbClicks || 0) % 2);
 return new Vec3(r, g, b);
}

visible.script:
'use strict';
export function update(value) { return true; }
export function cursorDown(event) { shared.cwbDown = (shared.cwbDown || 0) + 1; console.log('CWB_SCENE_DOWN', shared.cwbDown); }
export function cursorClick(event) { shared.cwbClicks = (shared.cwbClicks || 0) + 1; console.log('CWB_SCENE_CLICK', shared.cwbClicks); }
